scripts.calc_breakdown_sr.calc_sr.source_code:
def calc_sr(id_to_success: dict[int, bool]) -> dict[str, float]:
    sr = {
        "total": len(id_to_success),
        "success": sum(id_to_success.values()),
        "fail": len(id_to_success) - sum(id_to_success.values()),
    }
    # keep 2 decimal places
    sr["success_rate"] = round(sr["success"] / sr["total"], 4) * 100

    return sr

scripts.calc_breakdown_sr.parse_result.source_code:
def parse_result(log_file: str) -> dict[int, bool]:
    id_to_success: dict[int, bool] = {}

    # parse
    with open(log_file, "r") as f:
        for line in f:
            if "[Config file]" in line:
                id = os.path.basename(line.split()[-1]).split(".")[0]
            elif "[Result]" in line:
                if "(FAIL)" in line:
                    success = False
                elif "(PASS)" in line:
                    success = True
                else:
                    raise ValueError(f"Unknown result: {line}")
                id_to_success[int(id)] = success

    return id_to_success

scripts.calc_breakdown_sr.main.source_code:
def main(args: argparse.Namespace):
    id_to_success = parse_result(args.log_file)

    overall_sr = calc_sr(id_to_success)

    with open(args.config_file, "r") as f:
        config = json.load(f)

    # get achievable and unachievable tasks
    non_achievable = set()
    for task in config:
        task_id = int(task["task_id"])
        if (
            task["eval"]["eval_types"] == ["string_match"]
            and task["eval"]["reference_answers"].get("fuzzy_match", "") == "N/A"
        ):
            non_achievable.add(task_id)

    achievable_sr = calc_sr(
        {k: v for k, v in id_to_success.items() if k not in non_achievable}
    )
    unachievable_sr = calc_sr(
        {k: v for k, v in id_to_success.items() if k in non_achievable}
    )

    # get sr per website
    website_to_ids = {
        website: set()
        for website in [
            "shopping",
            "shopping_admin",
            "gitlab",
            "reddit",
            "map",
            "wikipedia",
        ]
    }
    for task in config:
        task_id = int(task["task_id"])
        cur_sites = task["sites"]
        for site in cur_sites:
            website_to_ids[site].add(task_id)

    website_sr = {
        website: calc_sr(
            {k: v for k, v in id_to_success.items() if k in website_to_ids[website]}
        )
        for website in website_to_ids
    }

    # by task type
    task_type_to_ids = {
        "info_seeking": set(),
        "site_nav": set(),
        "content_config": set(),
    }
    for task in config:
        task_id = int(task["task_id"])
        if task["eval"]["eval_types"] == ["string_match"]:
            task_type_to_ids["info_seeking"].add(task_id)
        elif task["eval"]["eval_types"] == ["url_match"]:
            task_type_to_ids["site_nav"].add(task_id)
        else:
            task_type_to_ids["content_config"].add(task_id)

    task_type_sr = {
        task_type: calc_sr(
            {k: v for k, v in id_to_success.items() if k in task_type_to_ids[task_type]}
        )
        for task_type in task_type_to_ids
    }

    print("=====================================")
    print("Overall SR:")
    print(overall_sr)
    print("=====================================")
    print("Achievable SR:")
    print(achievable_sr)
    print("=====================================")
    print("Unachievable SR:")
    print(unachievable_sr)
    print("=====================================")
    print("Website SR:")
    for website, sr in website_sr.items():
        print(website)
        print(sr)
    print("=====================================")
    print("Task type SR:")
    for task_type, sr in task_type_sr.items():
        print(task_type)
        print(sr)

scripts.check_error_runs.merge_logs.source_code:
def merge_logs(result_folder: str, args: argparse.Namespace) -> str:
    if not os.path.exists(f"{result_folder}/log_files.txt"):
        sys.exit(1)

    with open(f"{result_folder}/log_files.txt", "r") as f:
        log_files = f.readlines()

    merged_results = {}
    for file in log_files:
        with open(file.strip(), "r") as f:
            lines = f.readlines()

        cur_log: list[str] = []
        index = None
        for line in lines:
            if "[Config file]" in line:
                if (
                    cur_log
                    and index
                    and os.path.exists(f"{result_folder}/render_{index}.html")
                    and len(cur_log) >= 3
                ):
                    merged_results[index] = cur_log
                # update index and log
                index = line.split("/")[-1].split(".")[0]
                cur_log = [line]
            else:
                cur_log.append(line)

        if (
            cur_log
            and index
            and os.path.exists(f"{result_folder}/render_{index}.html")
            and len(cur_log) >= 3
        ):

            merged_results[index] = cur_log

    # sort by the key
    merged_results = dict(
        sorted(merged_results.items(), key=lambda x: int(x[0]))
    )

    merged_log_path = f"{result_folder}/tmp_merged_log.txt"
    with open(merged_log_path, "w") as f:
        for k, v in merged_results.items():
            for line in v:
                f.write(line)
    print(f"Number of examples: {len(merged_results)}")

    unlog_examples = []
    for i in range(812):
        if (
            os.path.exists(f"{result_folder}/render_{i}.html")
            and str(i) not in merged_results
        ):
            unlog_examples.append(i)

    print(f"Number of unlogged examples: {len(unlog_examples)}")
    print(unlog_examples)
    if (
        args.delete_errors
        or input("Do you want to delete these examples? (y/n)") == "y"
    ):
        for idx in unlog_examples:
            os.remove(f"{args.result_folder}/render_{idx}.html")

    unifinished_examples = [
        i for i in range(0, 812) if str(i) not in merged_results
    ]
    print(f"Number of unfinished examples: {len(unifinished_examples)}")
    print(unifinished_examples)

    return merged_log_path

scripts.check_error_runs.check_unhandled.source_code:
def check_unhandled_errors(args: argparse.Namespace) -> int:
    log_path = merge_logs(args.result_folder, args)
    with open(log_path, "r") as f:
        logs = f.read()

    error_examples = []
    for line in logs.split("\n"):
        if "[Config file]" in line:
            example_idx = line.split("/")[-1].split(".")[0]
        if "[Unhandled Error]" in line or "[OpenAI Error]" in line:
            error_examples.append(int(example_idx))

    num_errors = len(error_examples)
    print(f"Number of unhandled errors: {len(error_examples)}")
    print(error_examples)
    if (
        args.delete_errors
        or input("Do you want to delete these examples? (y/n)") == "y"
    ):
        for idx in error_examples:
            if os.path.exists(f"{args.result_folder}/render_{idx}.html"):
                os.remove(f"{args.result_folder}/render_{idx}.html")
    return num_errors

scripts.check_error_runs.check_unexpecte.source_code:
def check_unexpected_logout(args: argparse.Namespace) -> int:
    target_strings = set(
        [
            "Creating an account has many benefits: check out faster",
            "Welcome, please sign in",
            "Username or email",
            "Keep me logged in",
        ]
    )

    error_examples = []
    for render_file in glob.glob(f"{args.result_folder}/render_*.html"):
        with open(render_file, "r") as f:
            contents = f.read()
            if any([s in contents for s in target_strings]):
                task_id = int(
                    render_file.split("/")[-1].split(".")[0].split("_")[-1]
                )
                error_examples.append(task_id)
    print(f"Number of unexpected logout: {len(error_examples)}")
    print(error_examples)
    num_errors = len(error_examples)
    if (
        args.delete_errors
        or input("Do you want to delete these examples? (y/n)") == "y"
    ):
        for idx in error_examples:
            if os.path.exists(f"{args.result_folder}/render_{idx}.html"):
                os.remove(f"{args.result_folder}/render_{idx}.html")

    return num_errors

